import { MoreSmall } from '@wix/wix-ui-icons-common/lazy';
/* oxlint-disable no-console */
import classNames from 'classnames';
import React, { useContext, useEffect, useRef, useState } from 'react';

import { RicosContext } from './../../ricos-context/index.js';
import type { Helpers } from './../../ricos-types/index.js';
import { ReactPlayer } from './../../wix-react-player/index.js';
import { Image } from './../../ui-components/Components/image.js';
import { Slider } from './../../ui-components/Components/slider.js';
import {
  SLIDER_THUMB_VISIBILITY,
  SLIDER_TRACK_SIZE,
} from './../../ui-components/consts.js';
import { DownloadIcon, PlaybackIcon } from './../../ui-components/Icons/index.js';

import { IconButton } from '../components/icon-button.js';
import {
  AudioActionIcons,
  AudioDetails,
  AudioDuration,
  ContextMenu,
  SoundControl,
} from '../components/index.js';
import {
  AUDIO_ACTION_NAMES,
  AUDIO_BI_VALUES,
  AUDIO_TYPES,
  downloadFile,
  playbackRates,
} from '../consts.js';
import { AUDIO_CONTEXT_MENU, AUDIO_SLIDER } from '../data-hooks.js';
import styles from '../statics/styles/audio-scss.js';
import { AUDIO_TYPE } from '../types.js';

interface Props {
  url: string;
  coverImage?: { src?: string };
  authorName?: string;
  name?: string;
  disableDownload?: boolean;
  disabled?: boolean;
  isLoading?: boolean;
  helpers?: Helpers;
  saveDurationToData: (duration: $TSFixMe) => void;
  initialDuration?: number;
}

export const ReactPlayerWrapper: React.FC<Props> = ({
  url,
  authorName,
  name,
  disableDownload,
  coverImage,
  helpers,
  disabled,
  isLoading,
  saveDurationToData,
  initialDuration,
}) => {
  const { tabIndex, t, isMobile } = useContext(RicosContext);
  const [URL, setURL] = useState(url);
  const [isPlaying, setIsPlaying] = useState(false);
  const [duration, setDuration] = useState(initialDuration || 0);
  const [seeking, setSeeking] = useState(false);
  const [played, setPlayed] = useState(0);
  const [volume, setVolume] = useState(1);
  const [lastVolume, setLastVolume] = useState(1);
  const [playbackRate, setPlaybackRate] = useState(1);
  const [showPlaybackMenu, setShowPlaybackMenu] = useState(false);
  const [showContextMenu, setShowContextMenu] = useState(false);
  const [isStoppedBySeek, setIsStoppedBySeek] = useState(false);
  const slimDesign = !authorName && !name;
  const reactPlayerRef = useRef<ReactPlayer>(null);
  const onDownload = () => downloadFile(URL, name || 'untitled');
  const playBackMenuData = playbackRates.map(({ text, rate }) => ({
    text,
    onClick: () => {
      setPlaybackRate(rate);
      setShowPlaybackMenu(false);
    },
    selected: playbackRate === rate,
  }));
  const contextMenuOptions = {
    download: {
      text: 'Download',
      onClick: () => {
        helpers?.onViewerAction?.(
          AUDIO_TYPE,
          AUDIO_ACTION_NAMES.fileDownloaded,
          AUDIO_BI_VALUES.click
        );
        onDownload();
        setShowContextMenu(false);
      },
      dataHook: 'audio-download-icon',
      icon: DownloadIcon,
    },
    playback: {
      text: 'Playback Speed',
      onClick: () => {
        setShowContextMenu(false);
        setShowPlaybackMenu(true);
      },
      dataHook: 'audio-playback-icon',
      icon: PlaybackIcon,
    },
  };

  const contextMenuData = disableDownload
    ? [contextMenuOptions.playback]
    : [contextMenuOptions.download, contextMenuOptions.playback];

  const handleProgress = (state: $TSFixMe) => {
    if (!seeking) {
      setPlayed(state.played);
    }
  };
  const onEnded = () =>
    helpers?.onViewerAction?.(
      AUDIO_TYPE,
      AUDIO_ACTION_NAMES.playAudio,
      AUDIO_BI_VALUES.PLAYBACK_COMPLETED
    );

  const handleDuration = (num: number) => {
    setDuration(num);
    saveDurationToData(num);
    helpers?.mediaPluginsDetails?.({
      pluginId: AUDIO_TYPE,
      creator: authorName,
      title: name,
      track_duration: num?.toString(),
      type: AUDIO_TYPES.custom,
      url,
    });
  };
  const handleSeekChange = (num: number) => {
    isPlaying && setIsStoppedBySeek(true);
    handlePause();
    setSeeking(true);
    setPlayed(num);
  };
  const handlePlay = () => setIsPlaying(true);
  const handlePause = () => setIsPlaying(false);

  const handleContextMenuClick = () => {
    showContextMenu || showPlaybackMenu ? onClickOutside() : setShowContextMenu(true);
  };

  const handleSeekMouseUp = (num: number) => {
    reactPlayerRef?.current?.seekTo(num);
    setSeeking(false);
    isStoppedBySeek && handlePlay();
    setIsStoppedBySeek(false);
  };

  const handleMute = () => {
    if (volume !== 0) {
      setLastVolume(volume);
      setVolume(0);
    } else {
      setVolume(lastVolume);
    }
  };

  const onClickOutside = () => {
    setShowContextMenu(false);
    setShowPlaybackMenu(false);
  };

  useEffect(() => {
    handlePause();
    setURL(url);
  }, [url]);

  useEffect(() => {
    // This forces ReactPlayer to trigger an onDuration callback,
    //  which does not happen automaticly in the loadable.
    reactPlayerRef.current?.seekTo(0);
  }, []);

  return (
    <div>
      <div className={classNames(styles.customPlayer, { [styles.slim]: slimDesign })}>
        {coverImage?.src && (
          <Image
            containerProps={{ className: styles.coverImageContainer }}
            className={styles.coverImage}
            uri={coverImage.src}
            width={350}
            height={350}
            displayMode={'fill'}
            alt={t('Audio_Plugin_Cover_Alt')}
          />
        )}
        <div className={styles.trackDetailsContainer}>
          {!slimDesign && <AudioDetails authorName={authorName} title={name} />}
          <div className={styles.controlsContainer}>
            <div className={classNames(styles.controlsGroup, styles.sliderContainer)}>
              <AudioActionIcons
                handlePlay={handlePlay}
                handlePause={handlePause}
                isPlaying={isPlaying}
                disabled={disabled}
                isLoading={isLoading}
                helpers={helpers}
              />
              <Slider
                languageDir="ltr"
                value={played}
                dataHook={AUDIO_SLIDER}
                onChange={handleSeekChange}
                onChangeCommitted={handleSeekMouseUp}
                step="any"
                min={0}
                max={1}
                thumbVisibility={SLIDER_THUMB_VISIBILITY.hover}
                trackSize={SLIDER_TRACK_SIZE.small}
                tabIndex={tabIndex}
                disabled={isLoading}
                ariaLabel={t('Audio_Plugin_Elapsed_Time_Slider_AriaLabel')}
                ariaProps={{
                  'aria-valuenow': played,
                  'aria-valuetext': `${formatTime(played * duration)} of ${formatTime(duration)}`,
                }}
              />
              <AudioDuration isLoading={isLoading} played={played} duration={duration} />
            </div>
            <div className={styles.controlsGroup}>
              {!isMobile && (
                <SoundControl
                  volume={volume}
                  handleMute={handleMute}
                  muted={volume === 0}
                  handleVolumeChange={setVolume}
                  disabled={isLoading}
                />
              )}
              <IconButton
                tabIndex={tabIndex}
                isLoading={isLoading}
                onClick={handleContextMenuClick}
                aria-label={t('Audio_Plugin_More_Actions_Button_AriaLabel')}
                data-hook={AUDIO_CONTEXT_MENU}
                aria-haspopup="true"
                icon={<MoreSmall className={styles.audio_contextMenuIcon} />}
              >
                <ContextMenu
                  data-hook={AUDIO_CONTEXT_MENU}
                  onClickOutside={onClickOutside}
                  contextMenuData={contextMenuData}
                  playBackMenuData={playBackMenuData}
                  showContextMenu={showContextMenu}
                  showPlaybackMenu={showPlaybackMenu}
                />
              </IconButton>
            </div>
          </div>
        </div>
      </div>

      <ReactPlayer
        previewAriaLabel="Play audio"
        url={URL}
        ref={reactPlayerRef}
        playing={disabled ? false : isPlaying}
        playbackRate={playbackRate}
        onPause={handlePause}
        onPlay={handlePlay}
        width={0}
        height={0}
        controls={false}
        volume={volume}
        onProgress={handleProgress}
        onDuration={handleDuration}
        data-loaded={!isLoading}
        onEnded={onEnded}
        config={{
          file: {
            forceAudio: true,
          },
        }}
      />
    </div>
  );
};

const formatTime = (totalSeconds: number): string => {
  if (isNaN(totalSeconds) || totalSeconds < 0) {
    return '0:00';
  }
  const hours = Math.floor(totalSeconds / 3600);
  const minutes = Math.floor((totalSeconds % 3600) / 60);
  const seconds = Math.floor(totalSeconds % 60);

  const secondsStr = seconds.toString().padStart(2, '0');
  const minutesStr = minutes.toString().padStart(2, '0');

  if (hours > 0) {
    return `${hours}:${minutesStr}:${secondsStr}`;
  } else {
    return `${minutes}:${secondsStr}`;
  }
};
