import React, { useContext } from 'react';

import { RicosViewerContext } from './../../ricos-context/index.js';
import type { AudioNode } from './../../ricos-schema/next-schema/index.js';
import type { NodeViewRendererProps } from './../../ricos-types/index.js';

import { AUDIO_TYPE } from '../types.js';
import AudioViewer from './audio-viewer.js';

const Audio = ({ node, nodeIndex, NodeViewContainer }: NodeViewRendererProps) => {
  const { config } = useContext(RicosViewerContext);

  return (
    <NodeViewContainer key={node.id} node={node} nodeIndex={nodeIndex}>
      <AudioViewer node={node as AudioNode} settings={config[AUDIO_TYPE]} />
    </NodeViewContainer>
  );
};

export default Audio;
