import React from 'react';

import { ClickOutside } from './../../ui-components/ClickOutside/click-outside.js';

import { AUDIO_CONTEXT_COMMON_MENU, AUDIO_PLAYBACK_SPEED_MENU } from '../data-hooks.js';
import type { audioMenuDataType } from '../types.js';
import { DropdownMenu } from './dropdown-menu.js';

interface Props {
  onClickOutside: () => void;
  contextMenuData: audioMenuDataType;
  playBackMenuData: audioMenuDataType;
  showContextMenu: boolean;
  showPlaybackMenu: boolean;
}

export const ContextMenu: React.FC<Props> = ({
  onClickOutside,
  contextMenuData,
  playBackMenuData,
  showContextMenu,
  showPlaybackMenu,
}) => {
  return (
    <ClickOutside onClickOutside={onClickOutside}>
      {showContextMenu && (
        <DropdownMenu
          dataHook={AUDIO_CONTEXT_COMMON_MENU}
          options={contextMenuData}
          onClose={onClickOutside}
        />
      )}
      {showPlaybackMenu && (
        <DropdownMenu
          dataHook={AUDIO_PLAYBACK_SPEED_MENU}
          options={playBackMenuData}
          onClose={onClickOutside}
        />
      )}
    </ClickOutside>
  );
};
