import type { ViewerPluginCreator } from './../ricos-types/index.js';

import { DEFAULT_CONFIGS } from './defaults.js';
import type { AudioPluginViewerConfig } from './types.js';
import { AUDIO_TYPE } from './types.js';
import { nodeViewRenderers } from './viewer/node-view-renderers.js';

export type { AudioPluginViewerConfig } from './types.js';

export const pluginAudio: ViewerPluginCreator<AudioPluginViewerConfig> = config => {
  return {
    config: { ...DEFAULT_CONFIGS.viewer, ...config },
    type: AUDIO_TYPE,
    nodeViewRenderers,
  };
};
