import { SoundOffSmall, SoundSmall } from '@wix/wix-ui-icons-common/lazy';
import classNames from 'classnames';
import React, { useContext } from 'react';

import { RicosContext } from './../../ricos-context/index.js';
import { Slider } from './../../ui-components/Components/slider.js';
import { SLIDER_TRACK_SIZE } from './../../ui-components/consts.js';

import classes from '../statics/styles/sound-control-scss.js';
import { AUDIO_VOLUME_SLIDER } from './data-hooks.js';
import { IconButton } from './icon-button.js';

type Props = {
  volume: number;
  muted: boolean;
  handleMute: () => void;
  handleVolumeChange: (number: number) => void;
  disabled?: boolean;
};

export const SoundControl: React.FC<Props> = ({
  volume,
  muted,
  handleMute,
  handleVolumeChange,
  disabled,
}) => {
  const { t, tabIndex } = useContext(RicosContext);

  const onKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter') {
      handleMute();
      return;
    }
  };

  const SoundIconComponent = muted ? SoundOffSmall : SoundSmall;

  return (
    <div className={classNames(classes.root)}>
      <IconButton
        onKeyDown={onKeyDown}
        aria-label={
          muted
            ? t('Audio_Plugin_Volume_Control_Unmute_AriaLabel')
            : t('Audio_Plugin_Volume_Control_Mute_AriaLabel')
        }
        tabIndex={tabIndex}
        isLoading={disabled}
        icon={<SoundIconComponent onClick={handleMute} />}
      />
      <div className={classNames(classes.sliderContainer)}>
        <Slider
          min={0}
          max={1}
          step="0.1"
          value={volume}
          onChange={handleVolumeChange}
          onChangeCommitted={handleVolumeChange}
          languageDir="ltr"
          dataHook={AUDIO_VOLUME_SLIDER}
          trackSize={SLIDER_TRACK_SIZE.small}
          tabIndex={tabIndex}
          ariaLabel={t('Audio_Plugin_Volume_Control_Slider_AriaLabel')}
          className="has-custom-focus"
        />
      </div>
    </div>
  );
};
